import CryptoKit
import Foundation

/// What a project repo carries so a clone or worktree already knows how it works: apprentice's section of `AGENTS.md`,
/// and each CLI's copy of the skills and slash commands, generated from the one place the user edits them
/// (`.apprentice/skills/`, `.apprentice/commands/`) plus the built-in pipeline and help skills. The big site skills
/// stay global. A generated file says where its original is. One changed by hand is noticed and left alone until the
/// user says which to keep (`project sync --take-new | --keep-mine`), and the same goes for apprentice's section.
enum ProjectFiles {
    static let startMark = "<!-- apprentice:start (kept up to date by apprentice) -->"
    static let endMark = "<!-- apprentice:end -->"
    static let builtInSkills = ["apprentice-pipeline", "apprentice-help"]

    static let ignoreLines = ["limits.json", "limits.json.lock", "cache/"]
    static let worktreeLinksTemplate = """
        # What a parallel step's worktree needs that git does not hold, one pattern a line. A file is copied in,
        # a folder is linked (parallel steps must not change a linked folder).
        .env*

        """

    struct Record: Codable {
        /// Each generated file's text as written, by its hash.
        var files: [String: String] = [:]
        /// Paths the user chose to keep as they are.
        var kept: [String] = []
        var section: String? = nil
    }

    static func recordFile(_ folder: URL) -> URL { folder.appendingPathComponent(".apprentice/generated.json") }

    static func load(_ folder: URL) -> Record {
        (try? Data(contentsOf: recordFile(folder))).flatMap { try? JSONDecoder().decode(Record.self, from: $0) } ?? Record()
    }

    static func hash(_ text: String) -> String { SHA256.hash(data: Data(text.utf8)).map { String(format: "%02x", $0) }.joined() }

    // MARK: - what the files should say

    static var sectionBody: String {
        ((try? String(contentsOf: Repo.shipped("agent/project-section.md"), encoding: .utf8)) ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
    }

    static func block(_ body: String) -> String { startMark + "\n" + body + "\n" + endMark }

    /// The section as it stands in the file: its body, and the file split around it.
    static func split(_ text: String) -> (before: String, body: String, after: String)? {
        guard let start = text.range(of: startMark), let end = text.range(of: endMark, range: start.upperBound..<text.endIndex) else { return nil }
        return (String(text[..<start.lowerBound]), text[start.upperBound..<end.lowerBound].trimmingCharacters(in: .newlines), String(text[end.upperBound...]))
    }

    private static func frontMatter(_ text: String) -> (meta: [String: String], body: String) {
        let lines = text.components(separatedBy: "\n")
        guard lines.first == "---", let end = lines.dropFirst().firstIndex(of: "---") else { return ([:], text) }
        var meta: [String: String] = [:]
        for line in lines[1..<end] {
            if let colon = line.firstIndex(of: ":") { meta[String(line[..<colon]).trimmingCharacters(in: .whitespaces)] = line[line.index(after: colon)...].trimmingCharacters(in: .whitespaces) }
        }
        return (meta, lines[(end + 1)...].joined(separator: "\n"))
    }

    /// One CLI-readable skill from a skill's text, keeping its name and description.
    static func skillFile(name: String, text: String, from origin: String) -> String {
        let (meta, body) = frontMatter(text)
        let title = body.components(separatedBy: "\n").first { $0.hasPrefix("# ") }.map { String($0.dropFirst(2)) } ?? name
        let description = meta["description"] ?? title
        return "---\nname: \(name)\ndescription: \(description)\n---\n<!-- Generated by apprentice from \(origin): edit that one. -->\n\(body.trimmingCharacters(in: .newlines))\n"
    }

    /// One slash command in a CLI's own format. `$ARGUMENTS` is what the user typed after it.
    static func commandFile(format: String, description: String, body: String, origin: String) -> String {
        if format == "toml" {
            let prompt = body.replacingOccurrences(of: "$ARGUMENTS", with: "{{args}}").replacingOccurrences(of: "\\", with: "\\\\").replacingOccurrences(of: "\"", with: "\\\"")
            let desc = description.replacingOccurrences(of: "\"", with: "\\\"")
            return "# Generated by apprentice from \(origin): edit that one.\ndescription = \"\(desc)\"\nprompt = \"\"\"\n\(prompt)\n\"\"\"\n"
        }
        return "---\ndescription: \(description)\n---\n<!-- Generated by apprentice from \(origin): edit that one. -->\n\(body)\n"
    }

    /// The built-in slash commands only run the matching apprentice command, so behaviour stays in one place.
    static func builtInCommands() -> [(name: String, description: String, body: String)] {
        Help.book.entries.flatMap { e in
            e.slash.compactMap { pair -> (name: String, description: String, body: String)? in
                let parts = pair.split(separator: ":").map(String.init)
                guard parts.count == 2 else { return nil }
                let what: String
                switch parts[1] {
                case "audit": what = "Run `apprentice \(e.name) \(parts[1]) $ARGUMENTS`, read the brief it names, then review this pipeline with me."
                case "direct": what = "Run `apprentice \(e.name) \(parts[1]) $ARGUMENTS` in the shell, then do what it prints."
                default: what = "Run `apprentice \(e.name) \(parts[1]) $ARGUMENTS` in the shell and report what it prints."
                }
                return (parts[0], "apprentice \(e.name) \(parts[1])", what)
            }
        }
    }

    /// What a CLI calls a project's skill, from its file in `.apprentice/skills/`.
    static func skillName(_ url: URL) -> String {
        Playbooks.slugify(url.lastPathComponent == "SKILL.md" ? url.deletingLastPathComponent().lastPathComponent : url.deletingPathExtension().lastPathComponent)
    }

    /// The names of the project's own skills, for the buttons above its terminal.
    static func skillNames(_ folder: URL) -> [String] {
        guard let walk = FileManager.default.enumerator(at: folder.appendingPathComponent(".apprentice/skills"), includingPropertiesForKeys: nil) else { return [] }
        var out = Set<String>()
        for case let url as URL in walk where url.pathExtension == "md" && !skillName(url).isEmpty { out.insert(skillName(url)) }
        return out.sorted()
    }

    /// Every generated file, by its path in the project.
    static func wanted(_ folder: URL, clis: [AgentCLIs.CLI]) -> (files: [String: String], problems: [String]) {
        var files: [String: String] = [:]
        var problems: [String] = []
        var skills: [(name: String, text: String, origin: String)] = []
        for name in builtInSkills {
            if let text = try? String(contentsOf: Repo.shipped("skills/\(name)/SKILL.md"), encoding: .utf8) { skills.append((name, text, "apprentice's built-in \(name)")) }
        }
        let own = folder.appendingPathComponent(".apprentice/skills")
        if let walk = FileManager.default.enumerator(at: own, includingPropertiesForKeys: nil) {
            for case let url as URL in walk where url.pathExtension == "md" {
                let name = skillName(url)
                guard !name.isEmpty, let text = try? String(contentsOf: url, encoding: .utf8) else { continue }
                let rel = String(url.resolvingSymlinksInPath().path.dropFirst(folder.resolvingSymlinksInPath().path.count + 1))
                // A project's repo may be shared, so its skills pass the same check as playbooks before they are copied around.
                let leaks = Playbooks.leaks(text)
                if leaks.isEmpty { skills.append((name, text, rel)) } else { problems.append("\(rel) looks personal, so it was not copied: \(leaks[0])") }
            }
        }
        for dir in Set(clis.compactMap(\.skillsDir)) {
            for s in skills { files["\(dir)/\(s.name)/SKILL.md"] = skillFile(name: s.name, text: s.text, from: s.origin) }
        }
        var commands: [(name: String, description: String, body: String, origin: String)] = builtInCommands().map { ($0.name, $0.description, $0.body, "apprentice") }
        let ownCommands = folder.appendingPathComponent(".apprentice/commands")
        for url in ((try? FileManager.default.contentsOfDirectory(at: ownCommands, includingPropertiesForKeys: nil)) ?? []) where url.pathExtension == "md" {
            guard let text = try? String(contentsOf: url, encoding: .utf8) else { continue }
            let (meta, body) = frontMatter(text)
            let name = url.deletingPathExtension().lastPathComponent
            let leaks = Playbooks.leaks(body)
            if leaks.isEmpty { commands.append((name, meta["description"] ?? name, body.trimmingCharacters(in: .whitespacesAndNewlines), ".apprentice/commands/\(url.lastPathComponent)")) }
            else { problems.append(".apprentice/commands/\(url.lastPathComponent) looks personal, so it was not copied: \(leaks[0])") }
        }
        var seen = Set<String>()
        for cli in clis {
            guard let dir = cli.commandsDir, seen.insert(dir).inserted else { continue }
            for c in commands {
                let ext = cli.commandsFormat == "toml" ? "toml" : "md"
                files["\(dir)/\(c.name).\(ext)"] = commandFile(format: cli.commandsFormat, description: c.description, body: c.body, origin: c.origin)
            }
        }
        return (files, problems)
    }

    // MARK: - keeping them up to date

    /// A generated file changed by hand, or apprentice's section: nothing overwrites these until the user chooses.
    static func edited(_ folder: URL) -> [String] {
        let record = load(folder)
        var out: [String] = []
        for (path, recorded) in record.files where !record.kept.contains(path) {
            guard let now = try? String(contentsOf: folder.appendingPathComponent(path), encoding: .utf8) else { continue }
            if hash(now) != recorded { out.append(path) }
        }
        if let text = try? String(contentsOf: folder.appendingPathComponent("AGENTS.md"), encoding: .utf8), let parts = split(text), let recorded = record.section,
           hash(parts.body) != recorded, parts.body != sectionBody, !record.kept.contains("AGENTS.md") {
            out.append("AGENTS.md")
        }
        return out.sorted()
    }

    /// Brings the project up to date; returns anything the user should hear about. Quiet when nothing changed.
    @discardableResult
    static func sync(_ folder: URL, takeNew: Bool = false, keepMine: Bool = false) -> [String] {
        let fm = FileManager.default
        var record = load(folder)
        var notes: [String] = []
        let changedByHand = edited(folder)
        if keepMine { record.kept = Array(Set(record.kept + changedByHand)).sorted() }
        if takeNew { record.kept = [] }
        let waiting = keepMine || takeNew ? [] : changedByHand

        // AGENTS.md: only apprentice's own section changes; the user's text stays.
        let agents = folder.appendingPathComponent("AGENTS.md")
        if !record.kept.contains("AGENTS.md"), !waiting.contains("AGENTS.md") {
            let body = sectionBody
            let text = (try? String(contentsOf: agents, encoding: .utf8)) ?? "# \(Projects.info(folder)?.name ?? folder.lastPathComponent)\n"
            var updated: String
            if let parts = split(text) { updated = parts.before + block(body) + parts.after }
            else { updated = text.trimmingCharacters(in: .newlines) + "\n\n" + block(body) + "\n" }
            if updated != text { try? updated.write(to: agents, atomically: true, encoding: .utf8) }
            updated = ""
            record.section = hash(body)
        }
        for own in ["CLAUDE.md", "GEMINI.md"] {
            let file = folder.appendingPathComponent(own)
            if !fm.fileExists(atPath: file.path) { try? "@AGENTS.md\n".write(to: file, atomically: true, encoding: .utf8) }
        }
        let links = folder.appendingPathComponent(".apprentice/worktree-links")
        if !fm.fileExists(atPath: links.path) { try? worktreeLinksTemplate.write(to: links, atomically: true, encoding: .utf8) }
        ensureIgnored(folder)

        let (files, problems) = wanted(folder, clis: AgentCLIs.agents())
        notes += problems
        for (path, text) in files {
            let url = folder.appendingPathComponent(path)
            if record.kept.contains(path) || waiting.contains(path) { continue }
            let existing = try? String(contentsOf: url, encoding: .utf8)
            // A file of the user's own that was here first is theirs: it is never overwritten.
            if let existing, record.files[path] == nil, existing != text {
                record.kept.append(path)
                notes.append("\(path) is your own file, so apprentice's copy was not written there")
                continue
            }
            if existing != text {
                try? fm.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                try? text.write(to: url, atomically: true, encoding: .utf8)
            }
            record.files[path] = hash(text)
        }
        // What is no longer generated goes, unless it was changed by hand.
        for path in record.files.keys where files[path] == nil {
            let url = folder.appendingPathComponent(path)
            if let now = try? String(contentsOf: url, encoding: .utf8), hash(now) == record.files[path] {
                try? fm.removeItem(at: url)
                let parent = url.deletingLastPathComponent()
                if parent.lastPathComponent != "skills", ((try? fm.contentsOfDirectory(atPath: parent.path)) ?? []).isEmpty { try? fm.removeItem(at: parent) }
            }
            record.files[path] = nil
        }
        try? fm.createDirectory(at: recordFile(folder).deletingLastPathComponent(), withIntermediateDirectories: true)
        if let data = try? JSONEncoder().encode(record) {
            let pretty = (try? JSONSerialization.data(withJSONObject: JSONSerialization.jsonObject(with: data), options: [.prettyPrinted, .sortedKeys])) ?? data
            if (try? Data(contentsOf: recordFile(folder))) != pretty { try? pretty.write(to: recordFile(folder), options: .atomic) }
        }
        if !waiting.isEmpty {
            notes.append("changed by hand, left alone: \(waiting.joined(separator: ", ")) · apprentice project sync --keep-mine, or --take-new for apprentice's")
        }
        return notes
    }

    /// The cache holds outputs that can hold secrets: it must never reach git. Checked on every run.
    static func ensureIgnored(_ folder: URL) {
        let ignore = folder.appendingPathComponent(".apprentice/.gitignore")
        var lines = ((try? String(contentsOf: ignore, encoding: .utf8)) ?? "").components(separatedBy: "\n").filter { !$0.isEmpty }
        let missing = ignoreLines.filter { !lines.contains($0) }
        guard !missing.isEmpty else { return }
        lines += missing
        try? FileManager.default.createDirectory(at: ignore.deletingLastPathComponent(), withIntermediateDirectories: true)
        try? (lines.joined(separator: "\n") + "\n").write(to: ignore, atomically: true, encoding: .utf8)
    }

    /// `project sync [name] [--take-new | --keep-mine]`.
    static func command(_ a: Args) throws -> String {
        guard let p = Projects.find(a.pos.dropFirst().first) else { throw Fail(5, "not in a project folder · apprentice project sync <name>") }
        let notes = sync(p.folder, takeNew: a.has("take-new"), keepMine: a.has("keep-mine"))
        return (["\(p.name): up to date"] + notes).joined(separator: "\n")
    }
}
